"""P9-5 crypt placement script (Unreal MCP). Reads Docs/plans/p9_d1_layout.json (generated by gen_crypt_layout.py).

Usage (editor open on L_Monastery):
    python place_crypt.py --cats backdrop wall            # place categories (idempotent: removes the category's actors first)
    python place_crypt.py --cats wall --only W_OS         # place only records whose id contains this text (remove only those)
    python place_crypt.py --cats wall --check             # no placing; read back bounds/collision/materials of existing actors
    python place_crypt.py --hide-greybox                  # D-068: StaticMeshComponent.bVisible=false on the greybox shell
    python place_crypt.py --verify-greybox                # read back bVisible/collision and run the trace_world checks

Placed categories (P9-5): backdrop wall pitwall portal vault column ossuary tile stair soffit ceiling grate water.
P9-6a adds: lining (R4 greybox slab-face lining; F1 CA_Parapet_* rail enclosures), dress (CD_* dressing), decal (CD_Decal_* DecalActors).
P9-7 adds `light` (16 records, PointLight/SpotLight, label = id, folder Lighting/Crypt; G1/G2 yaw = DirectionalLight_1 yaw, pitch -78).
R2-C: `--cats light --check` also reads back each record's `volumetric_shadow` (bCastVolumetricShadow), cones, scattering, shadows, radius and lumens; the records hold the accepted scene values.
Fires, shaft cards, LFV and PP_Crypt are in place_lighting.py. Never run --cats light while PIE is running (it would spawn in the PIE world).
Dress skulls: actor yaw = record face_yaw + SKULL_OFFSETS[mesh] (override: --skull-offset SM_Skull_00=90 ...).
Decals: DecalActor via add_to_scene_from_class; decal.mi -> NewDecalComponent.decalMaterial, decal.size -> decalSize
(half-extents in depth, vertical, horizontal order, as given), record rotation as given (or + --decal-yaw-add degrees).
Every placed actor: transform set in ONE call (location+rotation+scale), label = id, outliner folder = record folder,
collision (NoCollision records: bUseDefaultCollision=false + bodyInstance.collisionProfileName=NoCollision, both read back;
"BlockAll (mesh hull)" records keep the mesh default), materials per the P9-5 table, then a bounds read-back (tolerance 3 cm).
"""
import argparse
import json
import os
import sys
import time

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "mcp"))
from ue import UE  # noqa: E402

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
LAYOUT = os.path.join(ROOT, "Docs", "plans", "p9_d1_layout.json")
S = "editor_toolset.toolsets.scene.SceneTools"
A = "editor_toolset.toolsets.actor.ActorTools"
O = "editor_toolset.toolsets.object.ObjectTools"
MAP = "/Game/LastBell/Maps/L_Monastery.L_Monastery"
MATDIR = "/Game/LastBell/Environments/Crypt/Materials/"
TOL = 3.0

import math  # noqa: E402

ORDER = ["backdrop", "wall", "pitwall", "portal", "vault", "column", "ossuary", "tile", "stair", "soffit",
         "ceiling", "grate", "water", "lining", "dress", "decal", "light"]
LF_DIR = "/Game/LastBell/Materials/Instances/"   # light function MIs (MI_LF_*)
# yaw added to a skull's face_yaw (world yaw its face must look toward) = the mesh's measured facing offset (P9-6a step 2)
SKULL_OFFSETS = {"SM_Skull_00": 90.0, "SM_Skull_01": 90.0, "SM_Skull_02": 90.0}   # measured (P9-6a step 2): at yaw 0 the face looks toward -Y (angle -90)
DECAL_YAW_ADD = [0.0]   # P9-6a step 3: added to every wall decal's yaw when the orientation check demands it (--decal-yaw-add)
DECAL_MI_DIRS = ["/Game/LastBell/Materials/Instances/", "/Game/LastBell/Environments/Crypt/Materials/",
                 "/Game/LastBell/Environments/Courtyard/Materials/"]
# label prefixes owned by each category (idempotent removal)
PREFIXES = {
    "backdrop": ["CA_Backdrop_"],
    "wall": ["CA_Wall_"],
    "pitwall": ["CA_PitWall_"],
    "portal": ["CA_Portal_"],
    "vault": ["CA_Vault_"],
    "column": ["CA_Pillar_", "CA_Capital_"],
    "ossuary": ["CA_Ossuary_"],
    "tile": ["CA_Tile_"],
    "stair": ["CA_Stair_"],
    "soffit": ["CA_Soffit_", "CA_Lintel_"],
    "ceiling": ["CA_CC_Beam_", "CA_CC_Corbel_", "CA_CC_Boards_", "CA_CC_Soil"],
    "grate": ["CA_CC_Grate", "CA_Grate_", "CA_GrateSky_"],
    "water": ["CA_Water_"],
    "lining": ["CA_Lining_", "CA_Parapet_"],
    "dress": ["CD_"],
    "decal": ["CD_Decal_"],
    "light": ["L_Crypt_"],
}
GREYBOX_LABELS = (["Rock_%03d" % i for i in range(17)] + ["CryptFloor_%d" % i for i in range(4)] +
                  ["Pit_Floor", "Pit_W", "Pit_E", "Pit_N", "Pit_S"] + ["Prop_Crypt_%d" % i for i in range(6)] +
                  ["Plinth_Crank"] + ["Stair_SacristyDown_%02d" % i for i in range(40)] +
                  ["Stair_CryptUp_%02d" % i for i in range(40)])
GREYBOX_FOLDERS = ["Crypt", "Crypt/Stairs"]
# trace checks: (name, x, y, start_z, end_z, expected hit z)
TRACES = [("landing (6550,-1100)", 6550, -1100, -100, -700, -600),
          ("flooded ledge (8250,-2450)", 8250, -2450, -100, -700, None),
          ("CC (10750,-900)", 10750, -900, -100, -700, None),
          ("pit-edge ledge (9550,-2388)", 9550, -2388, -100, -700, None),
          ("Sacristy stair step 20 centre", 7415, -1100, -100, -700, -285),
          ("Exit stair step 20 centre", 10650, -85, -150, -700, -285)]


def material_for(rec):
    i, cat = rec["id"], rec["cat"]
    if cat == "backdrop":
        return "MI_Crypt_Backdrop", False
    if cat == "water":
        return rec["mi"], None
    if cat == "lining":
        return "MI_Crypt_StoneWA", None
    if cat == "tile":   # P9-6a F2: SM_Ground has one slot (MI_Tiles, the pack cobble); every tile gets the crypt floor MI
        return "MI_Crypt_Floor", None
    if i == "CA_CC_Soil":
        return "MI_Crypt_Soil", None
    if i in ("CA_CC_GrateSky",) or i.startswith("CA_GrateSky_"):
        return "MI_Crypt_MoonSky", False
    return None, None


def slot_mats(rec):
    """P9-6a F4: per-slot MI overrides of a dress record, {slot index: MI name} (generator field `mi_slots`, keys = slot indices)."""
    return {int(k): v for k, v in (rec.get("mi_slots") or {}).items()}


def ang_diff(a, b):
    return (a - b + 180.0) % 360.0 - 180.0


def eff_rot(rec):
    """Final UE rotator [pitch, yaw, roll] of a record: skulls face_yaw + per-mesh offset; wall decals + DECAL_YAW_ADD."""
    p, y, r = rec["rot"]
    if "face_yaw" in rec:
        y = rec["face_yaw"] + SKULL_OFFSETS.get(rec["mesh"].split("/")[-1], 0.0)
    if rec["cat"] == "decal" and abs(r - 90.0) < 1e-6:
        y += DECAL_YAW_ADD[0]
    return [p, ((y + 180.0) % 360.0) - 180.0, r]


def rot_rows(p, y, r):
    P, Y, R = (math.radians(v) for v in (p, y, r))
    SP, CP, SY, CY, SR, CR = math.sin(P), math.cos(P), math.sin(Y), math.cos(Y), math.sin(R), math.cos(R)
    return [(CP * CY, CP * SY, SP),
            (SR * SP * CY - CR * SY, SR * SP * SY + CR * CY, -SR * CP),
            (-(CR * SP * CY + SR * SY), CY * SR - CR * SP * SY, CR * CP)]


def is_axis_aligned(rot):
    return abs(rot[0]) < 0.01 and abs(rot[2]) < 0.01 and abs(((rot[1] + 45.0) % 90.0) - 45.0) < 0.01


def expected_aabb(rec):
    """World AABB from the record's mesh-local bounds ('mbounds') and the final rotation; None if unknown."""
    mb = rec.get("mbounds")
    if not mb:
        return None
    lo, hi = mb
    rows = rot_rows(*eff_rot(rec))
    sc = rec["scale"]
    pts = []
    for cx in (lo[0], hi[0]):
        for cy in (lo[1], hi[1]):
            for cz in (lo[2], hi[2]):
                v = (cx * sc[0], cy * sc[1], cz * sc[2])
                pts.append([rec["loc"][k] + v[0] * rows[0][k] + v[1] * rows[1][k] + v[2] * rows[2][k] for k in range(3)])
    return [min(p[k] for p in pts) for k in range(3)], [max(p[k] for p in pts) for k in range(3)]


class Placer:
    def __init__(self):
        self.ue = UE()
        self._decal_mi = {}
        self.fix_collision = False   # --fix-collision (with --check): re-apply NoCollision incl. collisionEnabled on existing actors
        self.measured = {}   # dress records without generator mesh bounds: id -> (min, max) read back
        self._moon_yaw = None

    def call(self, ts, tool, args=None, tries=4):
        for k in range(tries):
            try:
                return self.ue.call(ts, tool, args)
            except Exception as e:  # connection reset etc.
                if k == tries - 1:
                    raise
                print("  retry %s.%s (%s)" % (tool, ts.split(".")[-1], str(e)[:120]))
                time.sleep(2)
                try:
                    self.ue = UE()
                except Exception:
                    time.sleep(3)

    # ---- helpers
    def label(self, a):
        return self.call(A, "get_label", {"actor": a})

    def find_prefix(self, prefix):
        acs = self.call(S, "find_actors", {"name": prefix, "tag": "", "collision_channels": []}) or []
        out = []
        for a in acs:
            if self.label(a).startswith(prefix):
                out.append(a)
        return out

    def remove_category(self, cat, only):
        n = 0
        for p in PREFIXES[cat]:
            for a in self.find_prefix(p):
                lbl = self.label(a)
                if only and only not in lbl:
                    continue
                if cat == "ceiling" and lbl.startswith("CA_CC_Grate"):
                    continue
                if cat == "dress" and lbl.startswith("CD_Decal_"):
                    continue
                self.call(S, "remove_from_scene", {"actor": a})
                n += 1
        return n

    def props(self, comp, names):
        r = self.call(O, "get_properties", {"instance": comp, "properties": names})
        return json.loads(r) if isinstance(r, str) else r

    def set_props(self, comp, values):
        return self.call(O, "set_properties", {"instance": comp, "values": json.dumps(values)})

    def comp0(self, actor):
        comps = self.call(A, "get_components", {"actor": actor})
        return comps[0]

    def bounds(self, actor):
        b = self.call(A, "get_actor_bounds", {"actor": actor})
        return b["min"], b["max"]

    def read_state(self, a, comp, rec, mat_expect):
        p = self.props(comp, ["bUseDefaultCollision", "bodyInstance", "castShadow", "overrideMaterials", "bVisible"])
        prof = p["bodyInstance"]["collisionProfileName"]
        mats = [m["refPath"].split("/")[-1].split(".")[0] if isinstance(m, dict) else str(m) for m in p["overrideMaterials"]]
        return {"profile": prof, "enabled": p["bodyInstance"].get("collisionEnabled"), "useDefault": p["bUseDefaultCollision"], "castShadow": p["castShadow"], "mats": mats}

    def resolve_decal_mi(self, name):
        if name not in self._decal_mi:
            for d in DECAL_MI_DIRS:
                if self.call("editor_toolset.toolsets.asset.AssetTools", "exists", {"path": d + name}):
                    self._decal_mi[name] = d + name + "." + name
                    break
            else:
                raise RuntimeError("decal MI not found: " + name)
        return self._decal_mi[name]

    def place_decal(self, rec):
        xf = {"location": dict(zip("xyz", rec["loc"])),
              "rotation": {"pitch": rec["rot"][0], "yaw": eff_rot(rec)[1], "roll": rec["rot"][2]},
              "scale": {"x": 1, "y": 1, "z": 1}}
        a = self.call(S, "add_to_scene_from_class", {"actor_type": {"refPath": "/Script/Engine.DecalActor"}, "name": rec["id"], "xform": xf})
        if not a:
            raise RuntimeError("decal spawn failed for " + rec["id"])
        a = a if isinstance(a, dict) else {"refPath": a}
        self.call(A, "set_actor_transform", {"actor": a, "xform": xf, "worldspace": True})
        self.call(A, "set_label", {"actor": a, "label": rec["id"]})
        self.call(S, "set_actor_folder", {"actor": a, "folder_path": rec["folder"]})
        comp = {"refPath": a["refPath"] + ".NewDecalComponent"}
        sz = rec["decal"]["size"]
        self.set_props(comp, {"decalMaterial": {"refPath": self.resolve_decal_mi(rec["decal"]["mi"])},
                              "decalSize": {"x": sz[0], "y": sz[1], "z": sz[2]}})
        return a, comp

    def verify_decal(self, rec, a, comp):
        p = self.props(comp, ["decalMaterial", "decalSize"])
        mat = (p["decalMaterial"] or {}).get("refPath", "").split("/")[-1].split(".")[0]
        sz = p["decalSize"]
        issues = []
        if mat != rec["decal"]["mi"]:
            issues.append("material %s != %s" % (mat, rec["decal"]["mi"]))
        e = rec["decal"]["size"]
        if max(abs(sz["x"] - e[0]), abs(sz["y"] - e[1]), abs(sz["z"] - e[2])) > 0.01:
            issues.append("decalSize %s != %s" % (sz, e))
        t = self.call(A, "get_actor_transform", {"actor": a, "worldspace": True})
        loc, rot = t["location"], t["rotation"]
        want = eff_rot(rec)
        dl = max(abs(loc["x"] - rec["loc"][0]), abs(loc["y"] - rec["loc"][1]), abs(loc["z"] - rec["loc"][2]))
        dr = max(abs(ang_diff(rot["pitch"], want[0])), abs(ang_diff(rot["yaw"], want[1])), abs(ang_diff(rot["roll"], want[2])))
        if dl > 0.1 or dr > 0.1:
            issues.append("transform dev loc %.2f rot %.2f" % (dl, dr))
        return not issues, dl, "; ".join(issues), {"mat": mat}

    # ---- P9-7 lights (cat "light")
    def moon_yaw(self):
        """World yaw of DirectionalLight_1 (the moon azimuth), read from the level (D1.15 step 3)."""
        if self._moon_yaw is None:
            dl = [a for a in (self.call(S, "find_actors", {"name": "DirectionalLight", "tag": "", "collision_channels": []}) or [])
                  if self.label(a) == "DirectionalLight"]
            if not dl:
                raise RuntimeError("DirectionalLight not found")
            self._moon_yaw = self.call(A, "get_actor_transform", {"actor": dl[0], "worldspace": True})["rotation"]["yaw"]
        return self._moon_yaw

    def light_rot(self, rec):
        p, y, r = rec["rot"]
        if rec["id"] in ("L_Crypt_Moon_G1", "L_Crypt_Moon_G2"):
            p, y, r = -78.0, self.moon_yaw(), 0.0
        return [p, y, r]

    def light_vals(self, rec):
        L = rec["light"]
        v = {"mobility": "Movable", "intensityUnits": "Lumens", "intensity": L["lumens"], "attenuationRadius": L["radius"],
             "lightColor": {"r": L["color"][0] / 255.0, "g": L["color"][1] / 255.0, "b": L["color"][2] / 255.0, "a": 1.0},
             "castShadows": bool(L["shadows"])}
        if "source_radius" in L:
            v["sourceRadius"] = L["source_radius"]
        if "volumetric_scattering" in L:
            v["volumetricScatteringIntensity"] = L["volumetric_scattering"]
        if "light_function" in L:
            n = L["light_function"]
            v["lightFunctionMaterial"] = {"refPath": LF_DIR + n + "." + n}
        if "volumetric_shadow" in L:   # R2-C: a record field now (moon spots: false, it stepped the shaft edges); read back by --check
            v["bCastVolumetricShadow"] = bool(L["volumetric_shadow"])
        return v

    def place_light(self, rec):
        L = rec["light"]
        rot = self.light_rot(rec)
        xf = {"location": dict(zip("xyz", rec["loc"])), "rotation": {"pitch": rot[0], "yaw": rot[1], "roll": rot[2]},
              "scale": {"x": 1, "y": 1, "z": 1}}
        a = self.call(S, "add_to_scene_from_class", {"actor_type": {"refPath": "/Script/Engine." + L["type"]}, "name": rec["id"], "xform": xf})
        if not a:
            raise RuntimeError("light spawn failed for " + rec["id"])
        a = a if isinstance(a, dict) else {"refPath": a}
        self.call(A, "set_actor_transform", {"actor": a, "xform": xf, "worldspace": True})
        self.call(A, "set_label", {"actor": a, "label": rec["id"]})
        self.call(S, "set_actor_folder", {"actor": a, "folder_path": rec["folder"]})
        comp = {"refPath": a["refPath"] + ".LightComponent0"}
        vals = self.light_vals(rec)
        if L["type"] == "SpotLight":
            vals["innerConeAngle"] = L["inner_cone"]
            vals["outerConeAngle"] = L["outer_cone"]
        self.set_props(comp, vals)
        return a, comp

    def verify_light(self, rec, a, comp):
        """read back every field (+-0.5 % values, +-0.1 deg angles, loc +-0.1 cm)"""
        L = rec["light"]
        want = self.light_vals(rec)
        names = list(want) + (["innerConeAngle", "outerConeAngle"] if L["type"] == "SpotLight" else [])
        got = self.props(comp, names)
        issues = []

        def close(g, e):
            return abs(g - e) <= max(0.005 * abs(e), 1e-6)

        for k, e in want.items():
            g = got.get(k)
            if k == "lightColor":
                if max(abs(g[c] - e[c]) for c in "rgb") > 1.0 / 255 + 1e-4:
                    issues.append("lightColor %s != %s" % (g, e))
            elif k == "lightFunctionMaterial":
                if (g or {}).get("refPath", "").split("/")[-1].split(".")[0] != L["light_function"]:
                    issues.append("lightFunctionMaterial %s" % g)
            elif isinstance(e, bool) or isinstance(e, str):
                if g != e:
                    issues.append("%s %s != %s" % (k, g, e))
            elif not close(g, e):
                issues.append("%s %s != %s" % (k, g, e))
        if L["type"] == "SpotLight":
            for k, e in (("innerConeAngle", L["inner_cone"]), ("outerConeAngle", L["outer_cone"])):
                if abs(got[k] - e) > 0.1:
                    issues.append("%s %s != %s" % (k, got[k], e))
        t = self.call(A, "get_actor_transform", {"actor": a, "worldspace": True})
        loc, rot, want_rot = t["location"], t["rotation"], self.light_rot(rec)
        dl = max(abs(loc[k] - rec["loc"]["xyz".index(k)]) for k in "xyz")
        dr = max(abs(ang_diff(rot["pitch"], want_rot[0])), abs(ang_diff(rot["yaw"], want_rot[1])), abs(ang_diff(rot["roll"], want_rot[2])))
        if dl > 0.1 or dr > 0.1:
            issues.append("transform dev loc %.2f rot %.2f" % (dl, dr))
        return not issues, dl, "; ".join(issues), {}

    def place_one(self, rec):
        if rec["cat"] == "light":
            return self.place_light(rec)
        if rec["cat"] == "decal":
            return self.place_decal(rec)
        rot = eff_rot(rec)
        xf = {"location": dict(zip("xyz", rec["loc"])),
              "rotation": {"pitch": rot[0], "yaw": rot[1], "roll": rot[2]},
              "scale": dict(zip("xyz", rec["scale"]))}
        mesh = rec["mesh"]
        asset = mesh if "." in mesh.split("/")[-1] else mesh + "." + mesh.split("/")[-1]
        a = self.call(S, "add_to_scene_from_asset", {"asset_path": asset, "name": rec["id"], "xform": xf})
        if not a:
            raise RuntimeError("spawn failed for " + rec["id"] + " " + asset)
        # one full transform call (never partial)
        self.call(A, "set_actor_transform", {"actor": a, "xform": xf, "worldspace": True})
        self.call(A, "set_label", {"actor": a, "label": rec["id"]})
        self.call(S, "set_actor_folder", {"actor": a, "folder_path": rec["folder"]})
        comp = self.comp0(a)
        vals = {}
        if rec["collision"] == "NoCollision":
            vals["bUseDefaultCollision"] = False
            # collisionEnabled must be set explicitly: with only the profile name the live body keeps QueryAndPhysics and
            # blocks traces (found in P9-6a: CA_Lining_* blocked trace_world while its profile read NoCollision)
            vals["bodyInstance"] = {"collisionProfileName": "NoCollision", "collisionEnabled": "NoCollision"}
        mi, shadow = material_for(rec)
        sm = slot_mats(rec)
        if mi:
            vals["overrideMaterials"] = [{"refPath": MATDIR + mi + "." + mi}]
        elif sm:   # unlisted slots below the highest index keep the mesh's own material (null override)
            vals["overrideMaterials"] = [({"refPath": MATDIR + sm[i] + "." + sm[i]} if i in sm else None) for i in range(max(sm) + 1)]
        if shadow is False:
            vals["castShadow"] = False
        if vals:
            self.set_props(comp, vals)
        return a, comp

    def verify(self, rec, a, comp):
        """returns (ok, message, state)"""
        if rec["cat"] == "light":
            return self.verify_light(rec, a, comp)
        if rec["cat"] == "decal":
            return self.verify_decal(rec, a, comp)
        mn, mx = self.bounds(a)
        got_min = [mn["x"], mn["y"], mn["z"]]
        got_max = [mx["x"], mx["y"], mx["z"]]
        exp = expected_aabb(rec) if rec["cat"] in ("dress", "lining") else (rec["aabb_min"], rec["aabb_max"])
        issues = []
        if exp is None:   # mesh bounds unknown to the generator: report the measured bounds, nothing to compare
            dev = 0.0
            self.measured[rec["id"]] = (got_min, got_max)
        elif rec["cat"] in ("dress", "lining") and not is_axis_aligned(eff_rot(rec)):
            # the expected box is the AABB of the rotated mesh-local box, which is a superset of the true mesh AABB when the
            # piece is rotated off-axis: only an overhang beyond the expected box counts as a deviation
            dev = max(max(e - g for g, e in zip(got_min, exp[0])), max(g - e for g, e in zip(got_max, exp[1])), 0.0)
        else:
            dev = max(max(abs(g - e) for g, e in zip(got_min, exp[0])),
                      max(abs(g - e) for g, e in zip(got_max, exp[1])))
        st = self.read_state(a, comp, rec, None)
        ok = dev <= TOL
        if not ok:
            issues.append("bounds dev %.1f (got %s..%s)" % (dev, [round(v, 1) for v in got_min], [round(v, 1) for v in got_max]))
        if rec["collision"] == "NoCollision":
            if st["profile"] != "NoCollision" or st["useDefault"] or st["enabled"] != "NoCollision":
                ok = False
                issues.append("collision not NoCollision (%s, enabled=%s, useDefault=%s)" % (st["profile"], st["enabled"], st["useDefault"]))
        else:
            if st["profile"] == "NoCollision":
                ok = False
                issues.append("expected mesh collision, got NoCollision")
        mi, shadow = material_for(rec)
        if mi and (not st["mats"] or st["mats"][0] != mi):
            ok = False
            issues.append("material %s != %s" % (st["mats"], mi))
        for si, smi in slot_mats(rec).items():
            if len(st["mats"]) <= si or st["mats"][si] != smi:
                ok = False
                issues.append("slot %d material %s != %s" % (si, st["mats"], smi))
        if shadow is False and st["castShadow"]:
            ok = False
            issues.append("castShadow still on")
        return ok, dev, "; ".join(issues), st

    # ---- categories
    def run_cats(self, cats, only, check):
        recs = json.load(open(LAYOUT))["placements"]
        summary = []
        for cat in cats:
            rs = [r for r in recs if r["cat"] == cat and (not only or only in r["id"])]
            removed = 0
            if not check:
                removed = self.remove_category(cat, only)
            print("== %s: %d records (removed %d existing)" % (cat, len(rs), removed), flush=True)
            fails, maxdev = [], 0.0
            for k, r in enumerate(rs):
                if check:
                    found = self.find_prefix(r["id"])
                    found = [f for f in found if self.label(f) == r["id"]]
                    if not found:
                        fails.append((r["id"], "missing"))
                        continue
                    a = found[0]
                    comp = self.comp0(a)
                    if r["cat"] == "light":
                        comp = {"refPath": a["refPath"] + ".LightComponent0"}
                    if self.fix_collision and r["collision"] == "NoCollision" and r["cat"] not in ("decal", "light"):
                        self.set_props(comp, {"bodyInstance": {"collisionProfileName": "NoCollision", "collisionEnabled": "NoCollision"}})
                else:
                    try:
                        a, comp = self.place_one(r)
                    except Exception as e:   # one failed record must not abort the run
                        fails.append((r["id"], "place error: " + str(e)[:200]))
                        print("  FAIL %s: place error %s" % (r["id"], str(e)[:200]), flush=True)
                        continue
                try:
                    ok, dev, msg, st = self.verify(r, a, comp)
                except Exception as e:
                    ok, dev, msg = False, 0.0, "verify error: " + str(e)[:200]
                maxdev = max(maxdev, dev)
                if not ok:
                    fails.append((r["id"], msg))
                    print("  FAIL %s: %s" % (r["id"], msg), flush=True)
                if (k + 1) % 20 == 0:
                    print("  ..%d/%d" % (k + 1, len(rs)), flush=True)
            print("   %s: placed/checked %d, pass %d, fail %d, max bounds deviation %.2f cm" %
                  (cat, len(rs), len(rs) - len(fails), len(fails), maxdev), flush=True)
            summary.append((cat, len(rs), len(rs) - len(fails), len(fails), maxdev))
        print("\nSUMMARY (cat, n, pass, fail, max dev cm)")
        for s in summary:
            print("  %-9s %4d %4d %3d  %.2f" % s)
        if self.measured:
            print("\nmeasured bounds (generator has no mesh bounds for these):")
            for k, (mn, mx) in sorted(self.measured.items()):
                print("  %s: %s .. %s" % (k, [round(v, 1) for v in mn], [round(v, 1) for v in mx]))
        return summary

    # ---- BlockAll dressing: the collision must really exist (trace_world through each piece)
    def verify_blockers(self):
        """Stake, cage and winch frame must block a trace (BlockAll with real shapes); prints distance/hit per probe."""
        ok = True
        probes = {"CD_SkeletonStake": [("x", 0.0)], "CD_CageOpen": [("x", 0.0)], "CD_WinchFrame": [("y", -110.0), ("y", 110.0)]}
        for lbl, plist in probes.items():
            found = [a for a in self.find_prefix(lbl) if self.label(a) == lbl]
            if not found:
                print("  MISSING", lbl)
                ok = False
                continue
            bmn, bmx = self.bounds(found[0])
            mn, mx = [bmn["x"], bmn["y"], bmn["z"]], [bmx["x"], bmx["y"], bmx["z"]]
            cx, cy = (mn[0] + mx[0]) / 2, (mn[1] + mx[1]) / 2
            z = mn[2] + min(60.0, (mx[2] - mn[2]) / 2)
            for ax, off in plist:
                n_hit = n_tot = 0
                first = None
                for dz in (20.0, 60.0, 120.0):          # several lines through the piece: open frames (cage) pass the centre line
                    for dl in (-30.0, -15.0, 0.0, 15.0, 30.0):
                        zz = mn[2] + dz
                        if ax == "x":   # along X at Y = cy + dl
                            a, b = (mn[0] - 40, cy + dl, zz), (mx[0] + 40, cy + dl, zz)
                        else:           # along Y at x = cx + off + dl (posts / sole plates)
                            a, b = (cx + off + dl, mn[1] - 40, zz), (cx + off + dl, mx[1] + 40, zz)
                        d = self.call(S, "trace_world", {"start": dict(zip("xyz", a)), "end": dict(zip("xyz", b))})
                        n_tot += 1
                        if d is not None:
                            n_hit += 1
                            first = first or d
                ok &= n_hit > 0
                print("  %-18s probe %s %+.0f: %d/%d lines blocked%s" % (lbl, ax, off, n_hit, n_tot,
                                                                         " (first distance %.1f)" % first if first else " -- NO HIT"))
        print("blockers:", "all block" if ok else "SOME DO NOT BLOCK")
        return ok

    # ---- greybox
    def greybox_actors(self):
        want = set(GREYBOX_LABELS)
        found = {}
        for fo in GREYBOX_FOLDERS:
            for a in self.call(S, "get_actors_in_folder", {"folder_path": fo, "recursive": False}):
                lbl = self.label(a)
                if lbl in want:
                    found[lbl] = a
        missing = sorted(want - set(found))
        return found, missing

    def hide_greybox(self):
        found, missing = self.greybox_actors()
        print("greybox actors found %d / %d, missing %s" % (len(found), len(GREYBOX_LABELS), missing))
        for lbl, a in found.items():
            comp = self.comp0(a)
            self.set_props(comp, {"bVisible": False})
        self.verify_greybox(found)

    def verify_greybox(self, found=None):
        if found is None:
            found, missing = self.greybox_actors()
            print("greybox actors found %d / %d, missing %s" % (len(found), len(GREYBOX_LABELS), missing))
        bad = 0
        profiles = {}
        for lbl, a in found.items():
            comp = self.comp0(a)
            p = self.props(comp, ["bVisible", "bodyInstance", "bUseDefaultCollision"])
            prof = p["bodyInstance"]["collisionProfileName"]
            profiles[prof] = profiles.get(prof, 0) + 1
            if p["bVisible"] or prof != "BlockAll":
                bad += 1
                print("  BAD", lbl, p["bVisible"], prof)
        print("greybox read-back: %d actors, bVisible true or non-BlockAll: %d, profiles %s" % (len(found), bad, profiles))
        for name, x, y, z0, z1, exp in TRACES:
            d = self.call(S, "trace_world", {"start": {"x": x, "y": y, "z": z0}, "end": {"x": x, "y": y, "z": z1}})
            hit = None if d is None else z0 - d
            print("  trace %-32s distance %s -> hit z %s (expected %s)" % (name, d, hit, exp))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--cats", nargs="*", default=[])
    ap.add_argument("--only", default="")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--hide-greybox", action="store_true")
    ap.add_argument("--verify-greybox", action="store_true")
    ap.add_argument("--skull-offset", nargs="*", default=[], help="SM_Skull_00=90 ...")
    ap.add_argument("--fix-collision", action="store_true")
    ap.add_argument("--decal-yaw-add", type=float, default=0.0)
    ap.add_argument("--verify-blockers", action="store_true", help="trace_world through the BlockAll dress pieces")
    args = ap.parse_args()
    for kv in args.skull_offset:
        k, v = kv.split("=")
        SKULL_OFFSETS[k] = float(v)
    DECAL_YAW_ADD[0] = args.decal_yaw_add
    for c in args.cats:
        if c not in ORDER:
            sys.exit("category %r not allowed (allowed: %s)" % (c, " ".join(ORDER)))
    p = Placer()
    p.fix_collision = args.fix_collision
    lvl = p.call(S, "get_current_level")
    if not str(lvl).endswith("L_Monastery"):
        sys.exit("editor is not on L_Monastery: %s" % lvl)
    if args.hide_greybox:
        p.hide_greybox()
    if args.verify_greybox:
        p.verify_greybox()
    if args.verify_blockers:
        p.verify_blockers()
    if args.cats:
        s = p.run_cats(args.cats, args.only, args.check)
        if any(x[3] for x in s):
            sys.exit(2)


if __name__ == "__main__":
    main()
